"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[31710],{9330:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"AccessCommandService","desc":"Cmdr commands for inspecting and overriding access.\\n\\nThe point of the package is that when somebody says \\"I can\'t get in\\", one command tells you why:\\n\\n```\\n> access-facts Quenty\\nQuenty\\n  isStaff = true (allowlist)\\n    override         p10000   abstained\\n    allowlist        p100     true       <-- decided\\n    groupRank        p0       false\\n```\\n\\nEvery command here is admin-gated, because [CmdrService] gates every command it registers on\\n[PermissionService] outside of Studio. Overriding a fact is granting an entitlement, so that gate is\\nthe whole reason overrides are safe to ship enabled.","realm":["Server"],"source":{"line":23,"path":"src/access/src/Server/Commands/AccessCommandService.lua"}}')}}]);